public class Solution {
    public boolean isPalindrome(String s) {
        int left = 0;
        int right = s.length() - 1;

        while (left < right) {
            if (!s.charAt(left).equals(s.charAt(right))) {
                return false;
            }
            left += 1;
            right -= 1;
        }

        return true;
    }

    public boolean isPalindrome(String s, int start, int end) {
        while (start <= end) {
            if (!s.charAt(start).equals(s.charAt(end))) {
                return false;
            }
            start++;
            end--;
        }

        return true;
    }

    public boolean isPalindrome(int[] nums) {
        int left = 0;
        int right = nums.length - 1;

        while (left < right) {
            if (!nums[left].equals(nums[right])) {
                return false;
            }
            left += 1;
            right -= 1;
        }

        return true;
    }

